package org.bukkit.scheduler;
public abstract class BukkitRunnable implements Runnable {private BukkitTask task;private void check(){if(task!=null)throw new IllegalStateException("Задача уже запущена");}private BukkitTask save(BukkitTask t){task=t;return t;}public BukkitTask runTask(org.bukkit.plugin.Plugin p){check();return save(org.bukkit.Bukkit.getScheduler().runTask(p,this));}public BukkitTask runTaskLater(org.bukkit.plugin.Plugin p,long d){check();return save(org.bukkit.Bukkit.getScheduler().runTaskLater(p,this,d));}public BukkitTask runTaskTimer(org.bukkit.plugin.Plugin p,long d,long t){check();return save(org.bukkit.Bukkit.getScheduler().runTaskTimer(p,this,d,t));}public void cancel(){if(task==null)throw new IllegalStateException("Задача не запущена");task.cancel();}public int getTaskId(){if(task==null)throw new IllegalStateException("Задача не запущена");return task.getTaskId();}}
